Object.keys(LV).forEach(s => {
  const [lv, ver] = s.split("-"); const base = (+lv)*1000 + (+ver)*100; const arr = LV[s];
  [...new Set(arr.map(x => x[1]))].sort((a,b) => a-b).forEach(ln => {
    const ws = arr.filter(x => x[1] === ln).map((x,j) => { const d = DICT[x[0]];
      return {n:j+1, h:x[0], p:d[0], t:d[1], id:d[2], en:"", g:0, ex:{zh:d[3], py:d[4], id:d[5]}}; });
    const nm = ln === 0 ? "Angka" : "Lesson " + ln;
    LESSONS.push({id: base+ln, set: s, name: nm, short: ln === 0 ? "Angka" : "L"+ln,
      sub: `HSK ${lv} (${ver}.0) · ${nm}`, words: ws, groups: [`HSK ${lv} ${ver}.0 · ${nm}`]});
  });
});

LESSONS.forEach(L => L.words.forEach(w => {
  w.l = L.id; w.k = L.id + "-" + w.n;
  // terjemahan Inggris: arti (HSK 1–3), contoh kalimat, catatan
  if (!w.en && EN_MEAN[w.h]) w.en = EN_MEAN[w.h];
  if (w.ex && EN_EX[w.ex.zh]) w.ex.en = EN_EX[w.ex.zh];
  if (w.note && EN_NOTE[w.note]) w.noteEn = EN_NOTE[w.note];
}));
const ALL = LESSONS.flatMap(L => L.words);

export const VERS = {"3":"3.0","2":"2.0"};
export { LESSONS, ALL };
export const lnum = id => id >= 1000 ? (id % 100 || "N") : id > 100 ? id - 100 : id;
// level HSK sebuah lesson (dipakai untuk label saat lesson digabung lintas HSK)
const LEVEL_OF = Object.fromEntries(LESSONS.map(L => [L.id, L.set.split("-")[0]]));
export const llevel = id => LEVEL_OF[id];
